import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"13、【同人】 离下乾上","description":"周易尚氏学 - 13、【同人】 离下乾上","frontmatter":{"title":"13、【同人】 离下乾上","description":"周易尚氏学 - 13、【同人】 离下乾上"},"headers":[],"relativePath":"zh/classics/shangshi/018.md","filePath":"zh/classics/shangshi/018.md"}'),s={name:"zh/classics/shangshi/018.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_13、【同人】-离下乾上" tabindex="-1">13、【同人】 离下乾上 <a class="header-anchor" href="#_13、【同人】-离下乾上" aria-label="Permalink to “13、【同人】 离下乾上”">​</a></h1><p>荀爽曰。乾舍于离。相与同居。九家曰。乾舍于离。同而为日。天日同明。故曰同人。是乾之居南。汉儒已言之矣。又荀爽注阴阳之义配日月云。乾舍于离。配日而居。坤舍于坎。配月而居。不惟乾南。且言坤北。而惠征君以为此汉儒言先天之铁证也。而欲减其迹。曰荀氏用鬼易。以乾归合离。坤归合坎释之。按乾归为大有。坤归为比。而荀氏所言者。则同人师。乃离归坎归也。于游归恒例。尚不能知。而欲减其证。其谁信之。故夫同人卦义。舍九家荀爽说。无有当者。伏坤为野。正义云。野以喻宽广。言和同于人。宜无远弗届也。易林九家荀爽皆以乾为河为海。是乾亦为大川。利涉谓五。中正有应。故传释为乾行。乾为君子。故利君子贞。贞卜问也。</p><p>彖曰。同人。柔得位得中而应乎乾。曰同人。同人曰。同人于野亨。利涉大川。乾行也。文明以健。中正而应。君子正也。唯君子为能通天下之志。</p><p>坤为天下。五应二故能通天下之志。详解在焦氏易诂中。</p><p>象曰。天与火。同人。君子以类族辨物。</p><p>易以阴阳相遇为类。(王引之繁称博引。释类为比。岂知皆非易之所谓类。)族。正义云。聚也。聚居一处。故曰同人。然所以能聚者。以其类也。设失类而为纯阳或纯阴。则不能聚矣。类族方能合异为同。乾阳物。坤阴物。同一物也。而分阴阳。辨别也。明也。同人五阳一阴。阴虽少。然五阳之所类也。即五阳之所同也。同则不分。然阴物阳物。判然不同。辨而明之。方知同之中有异。易之道。同性相违。异物相感。自类字失诂。义遂不明。</p><p>初九。同人于门。无咎。</p><p>初于二阴独近。故曰同人于门。象曰。出门同人。亦谓二近初。初出门即遇也。虞翻以乾为门。命四变阴以应初。若卦为家人者。而惠栋姚配中皆宗之。朱汉上强命初变。以艮为门。若卦为遁者。而毛奇龄焦循宗之。是皆曲说害理。二坤爻。坤亦为门户也。</p><h3 id="象曰。出门同人。又谁咎也。" tabindex="-1">象曰。出门同人。又谁咎也。 <a class="header-anchor" href="#象曰。出门同人。又谁咎也。" aria-label="Permalink to “象曰。出门同人。又谁咎也。”">​</a></h3><p>谁咎谓无咎。</p><p>六二。同人于宗。吝。</p><p>乾为主为宗。二五正应。故同人于宗。但卦五阳皆同于二。今二独亲五。则三四忌之。致吝之道也。下系云远近相取。而悔吝生。远谓应。近谓比。远取应则不能近取比。如无妄六二往应五而利。则不系初。近取比。则不能远取应。如中孚六四绝类上则不应初。而马匹亡。是也。是故远近万不能兼取。同人六二远应五。则有近不承阳之嫌。近承阳则失远应。故吝也。彼夫咸六二遁六二皆有应。象皆与此同。乃咸六二曰居吉。遁六二曰执之。皆戒其动。俾远近皆不取。不取则悔吝免也。旧说皆不知其故在三四。故鲜有得解者。</p><h3 id="象曰。同人于宗。吝道也。" tabindex="-1">象曰。同人于宗。吝道也。 <a class="header-anchor" href="#象曰。同人于宗。吝道也。" aria-label="Permalink to “象曰。同人于宗。吝道也。”">​</a></h3><p>许慎五经异义云。易曰同人于宗吝。言同姓相取。吝道也。按此皆不明易理。不知吝之故何在。而为此穿凿之说。同人二与五。与大有五与二同也。乃大有五应乾。无同姓之嫌。此独曰同姓。尚能通哉。</p><p>九三。伏戎于莽。升其高陵。三岁不兴。</p><p>巽为伏。为寇盗。(象失传。详焦氏易诂)为草莽。故曰伏戎于莽。乾为山。为陵。(象失传。详焦氏易诂)巽为高。乾为行。故曰升其高陵。乾为岁。离卦数三。故曰三岁。三阳遇阳。得敌。其行塞。故升高不兴也。</p><h3 id="象曰。伏戎于莽。敌刚也。三岁不兴。安行也。" tabindex="-1">象曰。伏戎于莽。敌刚也。三岁不兴。安行也。 <a class="header-anchor" href="#象曰。伏戎于莽。敌刚也。三岁不兴。安行也。" aria-label="Permalink to “象曰。伏戎于莽。敌刚也。三岁不兴。安行也。”">​</a></h3><p>敌刚即阳遇阳。安行谓行难。</p><p>九四。乘其墉。弗克攻。吉。</p><p>巽为墉。四居巽上。故曰乘其墉。乘墉据高。故不能攻之。然此爻不当位。无应予。承乘皆阳。困极矣。爻辞曰吉。则不得其义。象曰困而反则。似亦不得的解。而为此无可奈何之解。独虞翻命四变阴。当位有应。承乘皆阳。人人皆知其吉矣。然四变阴。则巽墉象毁。四居坎上。而谓乘其墉则不合矣。</p><h3 id="象曰。乘其墉。义弗克也。其吉。则困而反则也。" tabindex="-1">象曰。乘其墉。义弗克也。其吉。则困而反则也。 <a class="header-anchor" href="#象曰。乘其墉。义弗克也。其吉。则困而反则也。" aria-label="Permalink to “象曰。乘其墉。义弗克也。其吉。则困而反则也。”">​</a></h3><p>则法也。反则。言循分自守也。</p><p>九五。同人先号唃而后笑。大师克相遇。</p><p>此与屯六二义同。屯二欲上应五而为三四同性之阴所隔。故屯邅不进。然与五为正应。十年乃字。终必合也。同人九五欲应二。而为三四同性之阳所阻。故先号唃。然与二为正应。终必相遇。故后笑。伏震为笑为后。虞翻以互巽为号唃。卦伏坤。故曰师。相遇。谓遇二也。从前不能相遇者。以三四之伏戎为害也。后克而胜之。故与二相遇。</p><h3 id="象曰。同人之先。以中直也。大师相遇。言相克也。" tabindex="-1">象曰。同人之先。以中直也。大师相遇。言相克也。 <a class="header-anchor" href="#象曰。同人之先。以中直也。大师相遇。言相克也。" aria-label="Permalink to “象曰。同人之先。以中直也。大师相遇。言相克也。”">​</a></h3><p>端木国瑚曰。同人先天乾二中直。五无应。故号唃。后天离中虚。五得应。故后笑。以先后天解同人之先后。及中直之义。虽未确切。较胜于旧解。</p><p>上九。同人于郊。无悔。</p><p>居外卦之上。故曰同人于郊。乾为郊。上乘阳无应。远居郊外。旷莫与俦。故曰志未得。伏坤为志。</p><h3 id="象曰。同人于郊。志未得也。" tabindex="-1">象曰。同人于郊。志未得也。 <a class="header-anchor" href="#象曰。同人于郊。志未得也。" aria-label="Permalink to “象曰。同人于郊。志未得也。”">​</a></h3>',29)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
